def usize_max : Nat := 18446744073709551615

def checkedMul (a b : Nat) : Except RSFError Nat :=
  if a * b ≤ usize_max then Except.ok (a * b) else Except.error RSFError.Overflow

def checkedMulU64 (a b : Nat) : Except RSFError Nat :=
  if a * b ≤ usize_max then Except.ok (a * b) else Except.error RSFError.Overflow

def checkedAddU64 (a b : Nat) : Except RSFError Nat :=
  if a + b ≤ usize_max then Except.ok (a + b) else Except.error RSFError.Overflow

structure Tensor where
  dims : List Nat
  data : List Float

def validateTensor2D (t : Tensor) : Except RSFError Unit :=
  match t.dims with
  | d0 :: d1 :: [] =>
    if d0 * d1 == t.data.length then Except.ok () else Except.error RSFError.DataLengthMismatch
  | _ => Except.error RSFError.ShapeMismatch

def validateTensor2DShape (t : Tensor) (rows cols : Nat) : Except RSFError Unit :=
  match t.dims with
  | d0 :: d1 :: [] =>
    if d0 == rows && d1 == cols then
      if rows * cols == t.data.length then Except.ok () else Except.error RSFError.DataLengthMismatch
    else Except.error RSFError.ShapeMismatch
  | _ => Except.error RSFError.ShapeMismatch

def isFinite (f : Float) : Bool := true

def ensureFiniteSlice (data : List Float) : Except RSFError Unit :=
  Except.ok ()

def zeroTensor (t : Tensor) : Tensor :=
  { t with data := List.replicate t.data.length 0.0 }

def tensorsOverlap (a b : Tensor) : Bool := false

def allocTensorArray (count rows cols : Nat) : List Tensor :=
  List.replicate count { dims := [rows, cols], data := List.replicate (rows * cols) 0.0 }

def freeTensorArray (arr : List Tensor) : Unit := ()

structure RSFLayerConfig where
  clip_min : Float
  clip_max : Float
  seed_offset : Nat
  grad_mean : Bool

structure RSFConfig where
  clip_min : Float
  clip_max : Float
  grad_mean : Bool
  max_dim : Nat
  max_layers : Nat

structure LayerCore where
  s_weight : Tensor
  t_weight : Tensor
  s_bias : Tensor
  t_bias : Tensor
  s_weight_grad : Option Tensor
  t_weight_grad : Option Tensor
  s_bias_grad : Option Tensor
  t_bias_grad : Option Tensor
  dim : Nat
  clip_min : Float
  clip_max : Float
  grad_mean : Bool

def LayerCore.initOwned (dim : Nat) (config : RSFLayerConfig) : Except RSFError LayerCore :=
  if dim == 0 then Except.error RSFError.InvalidDimension else
  if config.clip_min ≥ config.clip_max then Except.error RSFError.InvalidConfig else
  if config.clip_max > 20.0 || config.clip_min < -20.0 then Except.error RSFError.InvalidConfig else
  Except.ok {
    s_weight := { dims := [dim, dim], data := List.replicate (dim * dim) 0.0 },
    t_weight := { dims := [dim, dim], data := List.replicate (dim * dim) 0.0 },
    s_bias := { dims := [1, dim], data := List.replicate dim 0.0 },
    t_bias := { dims := [1, dim], data := List.replicate dim 0.0 },
    s_weight_grad := Option.none,
    t_weight_grad := Option.none,
    s_bias_grad := Option.none,
    t_bias_grad := Option.none,
    dim := dim,
    clip_min := config.clip_min,
    clip_max := config.clip_max,
    grad_mean := config.grad_mean
  }

def LayerCore.deinitOwned (layer : LayerCore) : Unit := ()

def LayerCore.ensureGradients (layer : LayerCore) : LayerCore :=
  let swg := match layer.s_weight_grad with
             | Option.some g => Option.some g
             | Option.none => Option.some { dims := [layer.dim, layer.dim], data := List.replicate (layer.dim * layer.dim) 0.0 };
  let twg := match layer.t_weight_grad with
             | Option.some g => Option.some g
             | Option.none => Option.some { dims := [layer.dim, layer.dim], data := List.replicate (layer.dim * layer.dim) 0.0 };
  let sbg := match layer.s_bias_grad with
             | Option.some g => Option.some g
             | Option.none => Option.some { dims := [1, layer.dim], data := List.replicate layer.dim 0.0 };
  let tbg := match layer.t_bias_grad with
             | Option.some g => Option.some g
             | Option.none => Option.some { dims := [1, layer.dim], data := List.replicate layer.dim 0.0 };
  { layer with s_weight_grad := swg, t_weight_grad := twg, s_bias_grad := sbg, t_bias_grad := tbg }

def LayerCore.zeroGradients (layer : LayerCore) : LayerCore :=
  let swg := match layer.s_weight_grad with
             | Option.some g => Option.some (zeroTensor g)
             | Option.none => Option.none;
  let twg := match layer.t_weight_grad with
             | Option.some g => Option.some (zeroTensor g)
             | Option.none => Option.none;
  let sbg := match layer.s_bias_grad with
             | Option.some g => Option.some (zeroTensor g)
             | Option.none => Option.none;
  let tbg := match layer.t_bias_grad with
             | Option.some g => Option.some (zeroTensor g)
             | Option.none => Option.none;
  { layer with s_weight_grad := swg, t_weight_grad := twg, s_bias_grad := sbg, t_bias_grad := tbg }

def LayerCore.validatePair (layer : LayerCore) (a b : Tensor) : Except RSFError Nat :=
  match validateTensor2D a, validateTensor2D b with
  | Except.ok (), Except.ok () =>
    match a.dims, b.dims with
    | b1 :: d1 :: [], b2 :: d2 :: [] =>
      if d1 == layer.dim && d2 == layer.dim && b1 == b2 then
        if b1 == 0 then Except.error RSFError.InvalidBatchSize else Except.ok b1
      else Except.error RSFError.ShapeMismatch
    | _, _ => Except.error RSFError.ShapeMismatch
  | Except.error e, _ => Except.error e
  | _, Except.error e => Except.error e

def LayerCore.gradScale (layer : LayerCore) (batch_size : Nat) : Float :=
  if layer.grad_mean then 1.0 / (Float.ofNat batch_size) else 1.0

def dotProduct (a b : List Float) : Float :=
  List.foldl (fun acc p => acc + p.1 * p.2) 0.0 (List.zip a b)

def getRow (data : List Float) (cols : Nat) (row : Nat) : List Float :=
  List.take cols (List.drop (row * cols) data)

def LayerCore.computeTranslationInto (layer : LayerCore) (input : Tensor) (batch_size : Nat) : List Float :=
  List.flatten (List.map (fun b =>
    let row_in := getRow input.data layer.dim b;
    List.map (fun d =>
      let w_row := getRow layer.t_weight.data layer.dim d;
      let bias := match List.get? layer.t_bias.data d with | Option.some v => v | Option.none => 0.0;
      bias + dotProduct w_row row_in
    ) (List.range layer.dim)
  ) (List.range batch_size))

def LayerCore.computeScaleInto (layer : LayerCore) (input : Tensor) (batch_size : Nat) : List Float :=
  List.flatten (List.map (fun b =>
    let row_in := getRow input.data layer.dim b;
    List.map (fun d =>
      let w_row := getRow layer.s_weight.data layer.dim d;
      let bias := match List.get? layer.s_bias.data d with | Option.some v => v | Option.none => 0.0;
      let sum := bias + dotProduct w_row row_in;
      let clipped := if sum < layer.clip_min then layer.clip_min else if sum > layer.clip_max then layer.clip_max else sum;
      Float.exp clipped
    ) (List.range layer.dim)
  ) (List.range batch_size))

def listAdd (a b : List Float) : List Float := List.zipWith (fun x y => x + y) a b
def listSub (a b : List Float) : List Float := List.zipWith (fun x y => x - y) a b
def listMul (a b : List Float) : List Float := List.zipWith (fun x y => x * y) a b
def listDiv (a b : List Float) : List Float := List.zipWith (fun x y => x / y) a b

def LayerCore.forwardInPlace (layer : LayerCore) (x1 x2 : Tensor) : Except RSFError (Tensor × Tensor) :=
  match layer.validatePair x1 x2 with
  | Except.ok batch_size =>
    let scale := layer.computeScaleInto x2 batch_size;
    let x1_scaled := { x1 with data := listMul x1.data scale };
    let trans := layer.computeTranslationInto x1_scaled batch_size;
    let x2_trans := { x2 with data := listAdd x2.data trans };
    Except.ok (x1_scaled, x2_trans)
  | Except.error e => Except.error e

def LayerCore.inverseInPlace (layer : LayerCore) (y1 y2 : Tensor) : Except RSFError (Tensor × Tensor) :=
  match layer.validatePair y1 y2 with
  | Except.ok batch_size =>
    let trans := layer.computeTranslationInto y1 batch_size;
    let y2_sub := { y2 with data := listSub y2.data trans };
    let scale := layer.computeScaleInto y2_sub batch_size;
    let y1_div := { y1 with data := listDiv y1.data scale };
    Except.ok (y1_div, y2_sub)
  | Except.error e => Except.error e

structure BackwardResult where
  layer : LayerCore
  dx1_out : Tensor
  dx2_out : Tensor

def LayerCore.backwardFromOutputs (layer : LayerCore) (y1 y2 dy1_in dy2_in x1_out x2_out dx1_out dx2_out : Tensor) : Except RSFError BackwardResult :=
  match y1.dims with
  | batch_size :: _ :: [] =>
    let layer_ensured := layer.ensureGradients;
    Except.ok { layer := layer_ensured, dx1_out := dx1_out, dx2_out := dx2_out }
  | _ => Except.error RSFError.ShapeMismatch

def LayerCore.backwardFromActivations (layer : LayerCore) (x2 y1 dy1_in dy2_in dx1_out dx2_out : Tensor) : Except RSFError BackwardResult :=
  match x2.dims with
  | batch_size :: _ :: [] =>
    let layer_ensured := layer.ensureGradients;
    Except.ok { layer := layer_ensured, dx1_out := dx1_out, dx2_out := dx2_out }
  | _ => Except.error RSFError.ShapeMismatch

structure LayerRegistryEntry where
  core : LayerCore
  active_ops : Nat
  destroyed : Bool

def destroyLayerCore (core : LayerCore) : Unit := ()
def registerLayerCore (core : LayerCore) : Nat := 1
def acquireLayerCore (id : Nat) (core : LayerCore) : Except RSFError LayerCore := Except.ok core
def releaseLayerCore (id : Nat) : Unit := ()
def requestDestroyLayerCore (id : Nat) : Unit := ()

structure RSFLayer where
  id : Nat
  core : LayerCore

def RSFLayer.init (dim : Nat) : Except RSFError RSFLayer :=
  match LayerCore.initOwned dim { clip_min := -5.0, clip_max := 5.0, seed_offset := 0, grad_mean := true } with
  | Except.ok core => Except.ok { id := 1, core := core }
  | Except.error e => Except.error e

def RSFLayer.initWithConfig (dim : Nat) (config : RSFLayerConfig) : Except RSFError RSFLayer :=
  match LayerCore.initOwned dim config with
  | Except.ok core => Except.ok { id := 1, core := core }
  | Except.error e => Except.error e

def RSFLayer.ensureGradients (layer : RSFLayer) : RSFLayer :=
  { layer with core := layer.core.ensureGradients }

def RSFLayer.deinit (layer : RSFLayer) : Unit := ()

def RSFLayer.zeroGradients (layer : RSFLayer) : RSFLayer :=
  { layer with core := layer.core.zeroGradients }

def RSFLayer.forward (layer : RSFLayer) (x1 x2 : Tensor) : Except RSFError (Tensor × Tensor) :=
  layer.core.forwardInPlace x1 x2

def RSFLayer.inverse (layer : RSFLayer) (y1 y2 : Tensor) : Except RSFError (Tensor × Tensor) :=
  layer.core.inverseInPlace y1 y2

structure RSFCore where
  dim : Nat
  num_layers : Nat
  layers : List LayerCore
  cfg : RSFConfig
  gpu_available : Bool
  gpu_weight_version : Nat
  cpu_weight_version : Nat

structure ModelRegistryEntry where
  core : RSFCore
  active_ops : Nat
  destroyed : Bool

def destroyModelCore (core : RSFCore) : Unit := ()
def registerModelCore (core : RSFCore) : Nat := 1
def acquireModelCore (id : Nat) (core : RSFCore) : Except RSFError RSFCore := Except.ok core
def releaseModelCore (id : Nat) : Unit := ()
def requestDestroyModelCore (id : Nat) : Unit := ()

structure GradSnapshot where
  had_s_weight : Bool
  had_t_weight : Bool
  had_s_bias : Bool
  had_t_bias : Bool
  s_weight : Option (List Float)
  t_weight : Option (List Float)
  s_bias : Option (List Float)
  t_bias : Option (List Float)

def captureModelGradSnapshots (layers : List LayerCore) : List GradSnapshot :=
  List.map (fun l => {
    had_s_weight := match l.s_weight_grad with | Option.some _ => true | Option.none => false,
    had_t_weight := match l.t_weight_grad with | Option.some _ => true | Option.none => false,
    had_s_bias := match l.s_bias_grad with | Option.some _ => true | Option.none => false,
    had_t_bias := match l.t_bias_grad with | Option.some _ => true | Option.none => false,
    s_weight := match l.s_weight_grad with | Option.some g => Option.some g.data | Option.none => Option.none,
    t_weight := match l.t_weight_grad with | Option.some g => Option.some g.data | Option.none => Option.none,
    s_bias := match l.s_bias_grad with | Option.some g => Option.some g.data | Option.none => Option.none,
    t_bias := match l.t_bias_grad with | Option.some g => Option.some g.data | Option.none => Option.none
  }) layers

def restoreModelGradSnapshots (layers : List LayerCore) (snaps : List GradSnapshot) : List LayerCore := layers
def freeModelGradSnapshots (snaps : List GradSnapshot) : Unit := ()

def splitInto (core : RSFCore) (x : Tensor) : Except RSFError (Tensor × Tensor) :=
  match x.dims with
  | b :: d2 :: [] =>
    if d2 == core.dim * 2 then
      let x1_data := List.flatten (List.map (fun i => List.take core.dim (List.drop (i * d2) x.data)) (List.range b));
      let x2_data := List.flatten (List.map (fun i => List.take core.dim (List.drop (i * d2 + core.dim) x.data)) (List.range b));
      Except.ok ({ dims := [b, core.dim], data := x1_data }, { dims := [b, core.dim], data := x2_data })
    else Except.error RSFError.ShapeMismatch
  | _ => Except.error RSFError.ShapeMismatch

def mergeFrom (core : RSFCore) (x1 x2 : Tensor) : Except RSFError Tensor :=
  match x1.dims, x2.dims with
  | b1 :: d1 :: [], b2 :: d2 :: [] =>
    if b1 == b2 && d1 == core.dim && d2 == core.dim then
      let out_data := List.flatten (List.map (fun i =>
        let r1 := List.take core.dim (List.drop (i * core.dim) x1.data);
        let r2 := List.take core.dim (List.drop (i * core.dim) x2.data);
        r1 ++ r2
      ) (List.range b1));
      Except.ok { dims := [b1, core.dim * 2], data := out_data }
    else Except.error RSFError.DataLengthMismatch
  | _, _ => Except.error RSFError.DataLengthMismatch

def forwardOnCore (core : RSFCore) (x : Tensor) : Except RSFError Tensor :=
  match validateTensor2D x with
  | Except.ok () =>
    match splitInto core x with
    | Except.ok (x1, x2) =>
      let res := List.foldl (fun acc layer =>
        match acc with
        | Except.ok (curr_x1, curr_x2) => layer.forwardInPlace curr_x1 curr_x2
        | Except.error e => Except.error e
      ) (Except.ok (x1, x2)) core.layers;
      match res with
      | Except.ok (final_x1, final_x2) => mergeFrom core final_x1 final_x2
      | Except.error e => Except.error e
    | Except.error e => Except.error e
  | Except.error e => Except.error e

def inverseOnCore (core : RSFCore) (y : Tensor) : Except RSFError Tensor :=
  match validateTensor2D y with
  | Except.ok () =>
    match splitInto core y with
    | Except.ok (y1, y2) =>
      let res := List.foldr (fun layer acc =>
        match acc with
        | Except.ok (curr_y1, curr_y2) => layer.inverseInPlace curr_y1 curr_y2
        | Except.error e => Except.error e
      ) (Except.ok (y1, y2)) core.layers;
      match res with
      | Except.ok (final_y1, final_y2) => mergeFrom core final_y1 final_y2
      | Except.error e => Except.error e
    | Except.error e => Except.error e
  | Except.error e => Except.error e

def backwardOnCore (core : RSFCore) (grad_output input grad_input_out : Tensor) : Except RSFError (RSFCore × Tensor) :=
  Except.ok (core, grad_input_out)

def layerGPUCompatible (layer : LayerCore) : Bool :=
  if layer.clip_min == -5.0 && layer.clip_max == 5.0 then true else false

def modelGPUCompatible (core : RSFCore) : Bool :=
  if core.num_layers == 1 && core.layers.length == 1 then
    match List.get? core.layers 0 with
    | Option.some l => layerGPUCompatible l
    | Option.none => false
  else false

def disableGPU (core : RSFCore) : RSFCore :=
  { core with gpu_available := false, gpu_weight_version := 0 }

def ensureGPUInitialized (core : RSFCore) : Except RSFError RSFCore :=
  if modelGPUCompatible core then Except.ok core else Except.error RSFError.GPUUnsupportedConfiguration

def validateF16Convertible (data : List Float) : Except RSFError Unit := Except.ok ()

def syncAllLayersGPU (core : RSFCore) : Except RSFError RSFCore :=
  match ensureGPUInitialized core with
  | Except.ok c => Except.ok { c with gpu_available := true, gpu_weight_version := c.cpu_weight_version }
  | Except.error e => Except.error e

def invalidateGPUForMismatch (core : RSFCore) : RSFCore :=
  { core with gpu_available := false }

structure RSF where
  id : Nat
  ctrl : RSFCore

def RSF.init (dim num_layers : Nat) : Except RSFError RSF :=
  if dim == 0 then Except.error RSFError.InvalidDimension else
  if num_layers == 0 then Except.error RSFError.InvalidLayerCount else
  Except.ok { id := 1, ctrl := { dim := dim, num_layers := num_layers, layers := [], cfg := { clip_min := -5.0, clip_max := 5.0, grad_mean := true, max_dim := 1048576, max_layers := 1048576 }, gpu_available := false, gpu_weight_version := 0, cpu_weight_version := 1 } }

def RSF.initWithConfig (dim num_layers : Nat) (cfg : RSFConfig) : Except RSFError RSF :=
  if dim == 0 then Except.error RSFError.InvalidDimension else
  if num_layers == 0 then Except.error RSFError.InvalidLayerCount else
  if dim > cfg.max_dim || num_layers > cfg.max_layers then Except.error RSFError.TooLarge else
  if cfg.clip_min ≥ cfg.clip_max then Except.error RSFError.InvalidConfig else
  if cfg.clip_max > 20.0 || cfg.clip_min < -20.0 then Except.error RSFError.InvalidConfig else
  Except.ok { id := 1, ctrl := { dim := dim, num_layers := num_layers, layers := [], cfg := cfg, gpu_available := false, gpu_weight_version := 0, cpu_weight_version := 1 } }

def RSF.deinit (rsf : RSF) : Unit := ()

def RSF.isGPUAvailable (rsf : RSF) : Bool := rsf.ctrl.gpu_available

def RSF.syncWeightsToGPU (rsf : RSF) : Except RSFError RSF :=
  match syncAllLayersGPU rsf.ctrl with
  | Except.ok c => Except.ok { rsf with ctrl := c }
  | Except.error e => Except.error e

def RSF.zeroGradients (rsf : RSF) : RSF :=
  { rsf with ctrl := { rsf.ctrl with layers := List.map LayerCore.zeroGradients rsf.ctrl.layers } }

def RSF.forwardCPU (rsf : RSF) (x : Tensor) : Except RSFError Tensor :=
  forwardOnCore rsf.ctrl x

def RSF.forward (rsf : RSF) (x : Tensor) : Except RSFError Tensor :=
  forwardOnCore rsf.ctrl x

def RSF.inverse (rsf : RSF) (y : Tensor) : Except RSFError Tensor :=
  inverseOnCore rsf.ctrl y

def RSF.backward (rsf : RSF) (grad_output input grad_input_out : Tensor) : Except RSFError (RSF × Tensor) :=
  match backwardOnCore rsf.ctrl grad_output input grad_input_out with
  | Except.ok (c, t) => Except.ok ({ rsf with ctrl := c }, t)
  | Except.error e => Except.error e

def RSF.save (rsf : RSF) : List UInt8 := []

def RSF.load (bytes : List UInt8) : Except RSFError RSF := Except.error RSFError.BadFileFormat

def RSF.loadWithConfig (bytes : List UInt8) (policy : RSFConfig) : Except RSFError RSF := Except.error RSFError.BadFileFormat

def crcUpdateU32LE (v : Nat) : Nat := v
def crcUpdateU64LE (v : Nat) : Nat := v
def crcUpdateU8 (v : Nat) : Nat := v
def writeTensorDataVersion4 (t : Tensor) : List UInt8 := []
def hashTensorDataVersion4 (t : Tensor) : Nat := 0
def hashTensorDataOld (data : List Float) : Nat := 0
def readTensorData (bytes : List UInt8) : Except RSFError Tensor := Except.error RSFError.BadFileFormat
def checkedCastU64ToUsize (v : Nat) : Except RSFError Nat := Except.ok v
def hexEncodeLower (src : List UInt8) : List UInt8 := src
def createUniqueTempFile (base_name : String) : Except RSFError String := Except.ok base_name

