def usize_max : Nat := 18446744073709551615

def checkedMul (a b : Nat) : Except RSFError Nat :=
  if a * b ≤ usize_max then Except.ok (a * b) else Except.error RSFError.Overflow

def checkedMulU64 (a b : Nat) : Except RSFError Nat :=
  if a * b ≤ usize_max then Except.ok (a * b) else Except.error RSFError.Overflow

def checkedAddU64 (a b : Nat) : Except RSFError Nat :=
  if a + b ≤ usize_max then Except.ok (a + b) else Except.error RSFError.Overflow

structure Tensor where
  dims : List Nat
  data : List Float

def validateTensor2D (t : Tensor) : Except RSFError Unit :=
  match t.dims with
  | d0 :: d1 :: [] =>
    if d0 * d1 == t.data.length then Except.ok () else Except.error RSFError.DataLengthMismatch
  | _ => Except.error RSFError.ShapeMismatch

def validateTensor2DShape (t : Tensor) (rows cols : Nat) : Except RSFError Unit :=
  match t.dims with
  | d0 :: d1 :: [] =>
    if d0 == rows && d1 == cols then
      if rows * cols == t.data.length then Except.ok () else Except.error RSFError.DataLengthMismatch
    else Except.error RSFError.ShapeMismatch
  | _ => Except.error RSFError.ShapeMismatch

def isFinite (f : Float) : Bool := true

def ensureFiniteSlice (data : List Float) : Except RSFError Unit :=
  Except.ok ()

def zeroTensor (t : Tensor) : Tensor :=
  { t with data := List.replicate t.data.length 0.0 }

def tensorsOverlap (a b : Tensor) : Bool := false

def allocTensorArray (count rows cols : Nat) : List Tensor :=
  List.replicate count { dims := [rows, cols], data := List.replicate (rows * cols) 0.0 }

def freeTensorArray (arr : List Tensor) : Unit := ()

structure RSFLayerConfig where
  clip_min : Float
  clip_max : Float
  seed_offset : Nat
  grad_mean : Bool

structure RSFConfig where
  clip_min : Float
  clip_max : Float
  grad_mean : Bool
  max_dim : Nat
  max_layers : Nat

structure LayerCore where
  s_weight : Tensor
  t_weight : Tensor
  s_bias : Tensor
  t_bias : Tensor
  s_weight_grad : Option Tensor
  t_weight_grad : Option Tensor
  s_bias_grad : Option Tensor
  t_bias_grad : Option Tensor
  dim : Nat
  clip_min : Float
  clip_max : Float
  grad_mean : Bool

def LayerCore.initOwned (dim : Nat) (config : RSFLayerConfig) : Except RSFError LayerCore :=
  if dim == 0 then Except.error RSFError.InvalidDimension else
  if config.clip_min ≥ config.clip_max then Except.error RSFError.InvalidConfig else
  if config.clip_max > 20.0 || config.clip_min < -20.0 then Except.error RSFError.InvalidConfig else
  Except.ok {
    s_weight := { dims := [dim, dim], data := List.replicate (dim * dim) 0.0 },
    t_weight := { dims := [dim, dim], data := List.replicate (dim * dim) 0.0 },
    s_bias := { dims := [1, dim], data := List.replicate dim 0.0 },
    t_bias := { dims := [1, dim], data := List.replicate dim 0.0 },
    s_weight_grad := Option.none,
    t_weight_grad := Option.none,
    s_bias_grad := Option.none,
    t_bias_grad := Option.none,
    dim := dim,
    clip_min := config.clip_min,
    clip_max := config.clip_max,
    grad_mean := config.grad_mean
  }

def LayerCore.deinitOwned (layer : LayerCore) : Unit := ()

def LayerCore.ensureGradients (layer : LayerCore) : LayerCore :=
  let swg := match layer.s_weight_grad with
             | Option.some g => Option.some g
             | Option.none => Option.some { dims := [layer.dim, layer.dim], data := List.replicate (layer.dim * layer.dim) 0.0 };
  let twg := match layer.t_weight_grad with
             | Option.some g => Option.some g
             | Option.none => Option.some { dims := [layer.dim, layer.dim], data := List.replicate (layer.dim * layer.dim) 0.0 };
  let sbg := match layer.s_bias_grad with
             | Option.some g => Option.some g
             | Option.none => Option.some { dims := [1, layer.dim], data := List.replicate layer.dim 0.0 };
  let tbg := match layer.t_bias_grad with
             | Option.some g => Option.some g
             | Option.none => Option.some { dims := [1, layer.dim], data := List.replicate layer.dim 0.0 };
  { layer with s_weight_grad := swg, t_weight_grad := twg, s_bias_grad := sbg, t_bias_grad := tbg }

def LayerCore.zeroGradients (layer : LayerCore) : LayerCore :=
  let swg := match layer.s_weight_grad with
             | Option.some g => Option.some (zeroTensor g)
             | Option.none => Option.none;
  let twg := match layer.t_weight_grad with
             | Option.some g => Option.some (zeroTensor g)
             | Option.none => Option.none;
  let sbg := match layer.s_bias_grad with
             | Option.some g => Option.some (zeroTensor g)
             | Option.none => Option.none;
  let tbg := match layer.t_bias_grad with
             | Option.some g => Option.some (zeroTensor g)
             | Option.none => Option.none;
  { layer with s_weight_grad := swg, t_weight_grad := twg, s_bias_grad := sbg, t_bias_grad := tbg }

def LayerCore.validatePair (layer : LayerCore) (a b : Tensor) : Except RSFError Nat :=
  match validateTensor2D a, validateTensor2D b with
  | Except.ok (), Except.ok () =>
    match a.dims, b.dims with
    | b1 :: d1 :: [], b2 :: d2 :: [] =>
      if d1 == layer.dim && d2 == layer.dim && b1 == b2 then
        if b1 == 0 then Except.error RSFError.InvalidBatchSize else Except.ok b1
      else Except.error RSFError.ShapeMismatch
    | _, _ => Except.error RSFError.ShapeMismatch
  | Except.error e, _ => Except.error e
  | _, Except.error e => Except.error e

def LayerCore.gradScale (layer : LayerCore) (batch_size : Nat) : Float :=
  if layer.grad_mean then 1.0 / (Float.ofNat batch_size) else 1.0

def dotProduct (a b : List Float) : Float :=
  List.foldl (fun acc p => acc + p.1 * p.2) 0.0 (List.zip a b)

def getRow (data : List Float) (cols : Nat) (row : Nat) : List Float :=
  List.take cols (List.drop (row * cols) data)

def LayerCore.computeTranslationInto (layer : LayerCore) (input : Tensor) (batch_size : Nat) : List Float :=
  List.flatten (List.map (fun b =>
    let row_in := getRow input.data layer.dim b;
    List.map (fun d =>
      let w_row := getRow layer.t_weight.data layer.dim d;
      let bias := match List.get? layer.t_bias.data d with | Option.some v => v | Option.none => 0.0;
      bias + dotProduct w_row row_in
    ) (List.range layer.dim)
  ) (List.range batch_size))

def LayerCore.computeScaleInto (layer : LayerCore) (input : Tensor) (batch_size : Nat) : List Float :=
  List.flatten (List.map (fun b =>
    let row_in := getRow input.data layer.dim b;
    List.map (fun d =>
      let w_row := getRow layer.s_weight.data layer.dim d;
      let bias := match List.get? layer.s_bias.data d with | Option.some v => v | Option.none => 0.0;
      let sum := bias + dotProduct w_row row_in;
      let clipped := if sum < layer.clip_min then layer.clip_min else if sum > layer.clip_max then layer.clip_max else sum;
      Float.exp clipped
    ) (List.range layer.dim)
  ) (List.range batch_size))

def listAdd (a b : List Float) : List Float := List.zipWith (fun x y => x + y) a b
def listSub (a b : List Float) : List Float := List.zipWith (fun x y => x - y) a b
def listMul (a b : List Float) : List Float := List.zipWith (fun x y => x * y) a b
def listDiv (a b : List Float) : List Float := List.zipWith (fun x y => x / y) a b

def LayerCore.forwardInPlace (layer : LayerCore) (x1 x2 : Tensor) : Except RSFError (Tensor × Tensor) :=
  match layer.validatePair x1 x2 with
  | Except.ok batch_size =>
    let scale := layer.computeScaleInto x2 batch_size;
    let x1_scaled := { x1 with data := listMul x1.data scale };
    let trans := layer.computeTranslationInto x1_scaled batch_size;
    let x2_trans := { x2 with data := listAdd x2.data trans };
    Except.ok (x1_scaled, x2_trans)
  | Except.error e => Except.error e

def LayerCore.inverseInPlace (layer : LayerCore) (y1 y2 : Tensor) : Except RSFError (Tensor × Tensor) :=
  match layer.validatePair y1 y2 with
  | Except.ok batch_size =>
    let trans := layer.computeTranslationInto y1 batch_size;
    let y2_sub := { y2 with data := listSub y2.data trans };
    let scale := layer.computeScaleInto y2_sub batch_size;
    let y1_div := { y1 with data := listDiv y1.data scale };
    Except.ok (y1_div, y2_sub)
  | Except.error e => Except.error e

structure BackwardResult where
  layer : LayerCore
  dx1_out : Tensor
  dx2_out : Tensor

def LayerCore.backwardFromOutputs (layer : LayerCore) (y1 y2 dy1_in dy2_in x1_out x2_out dx1_out dx2_out : Tensor) : Except RSFError BackwardResult :=
  match y1.dims with
  | batch_size :: _ :: [] =>
    let layer_ensured := layer.ensureGradients;
    Except.ok { layer := layer_ensured, dx1_out := dx1_out, dx2_out := dx2_out }
  | _ => Except.error RSFError.ShapeMismatch

def LayerCore.backwardFromActivations (layer : LayerCore) (x2 y1 dy1_in dy2_in dx1_out dx2_out : Tensor) : Except RSFError BackwardResult :=
  match x2.dims with
  | batch_size :: _ :: [] =>
    let layer_ensured := layer.ensureGradients;
    Except.ok { layer := layer_ensured, dx1_out := dx1_out, dx2_out := dx2_out }
  | _ => Except.error RSFError.ShapeMismatch

structure LayerRegistryEntry where
  core : LayerCore
  active_ops : Nat
  destroyed : Bool

def destroyLayerCore (core : LayerCore) : Unit := ()
def registerLayerCore (core : LayerCore) : Nat := 1
def acquireLayerCore (id : Nat) (core : LayerCore) : Except RSFError LayerCore := Except.ok core
def releaseLayerCore (id : Nat) : Unit := ()
def requestDestroyLayerCore (id : Nat) : Unit := ()

structure RSFLayer where
  id : Nat
  core : LayerCore

def RSFLayer.init (dim : Nat) : Except RSFError RSFLayer :=
  match LayerCore.initOwned dim { clip_min := -5.0, clip_max := 5.0, seed_offset := 0, grad_mean := true } with
  | Except.ok core => Except.ok { id := 1, core := core }
  | Except.error e => Except.error e

def RSFLayer.initWithConfig (dim : Nat) (config : RSFLayerConfig) : Except RSFError RSFLayer :=
  match LayerCore.initOwned dim config with
  | Except.ok core => Except.ok { id := 1, core := core }
  | Except.error e => Except.error e

def RSFLayer.ensureGradients (layer : RSFLayer) : RSFLayer :=
  { layer with core := layer.core.ensureGradients }

def RSFLayer.deinit (layer : RSFLayer) : Unit := ()

def RSFLayer.zeroGradients (layer : RSFLayer) : RSFLayer :=
  { layer with core := layer.core.zeroGradients }

def RSFLayer.forward (layer : RSFLayer) (x1 x2 : Tensor) : Except RSFError (Tensor × Tensor) :=
  layer.core.forwardInPlace x1 x2

def RSFLayer.inverse (layer : RSFLayer) (y1 y2 : Tensor) : Except RSFError (Tensor × Tensor) :=
  layer.core.inverseInPlace y1 y2

structure RSFCore where
  dim : Nat
  num_layers : Nat
  layers : List LayerCore
  cfg : RSFConfig
  gpu_available : Bool
  gpu_weight_version : Nat
