structure GradSnapshot where
  had_s_weight : Bool
  had_t_weight : Bool
  had_s_bias : Bool
  had_t_bias : Bool
  s_weight : Option (List Float)
  t_weight : Option (List Float)
  s_bias : Option (List Float)
  t_bias : Option (List Float)

def captureModelGradSnapshots (layers : List LayerCore) : List GradSnapshot :=
  List.map (fun l => {
    had_s_weight := match l.s_weight_grad with | Option.some _ => true | Option.none => false,
    had_t_weight := match l.t_weight_grad with | Option.some _ => true | Option.none => false,
    had_s_bias := match l.s_bias_grad with | Option.some _ => true | Option.none => false,
    had_t_bias := match l.t_bias_grad with | Option.some _ => true | Option.none => false,
    s_weight := match l.s_weight_grad with | Option.some g => Option.some g.data | Option.none => Option.none,
    t_weight := match l.t_weight_grad with | Option.some g => Option.some g.data | Option.none => Option.none,
    s_bias := match l.s_bias_grad with | Option.some g => Option.some g.data | Option.none => Option.none,
    t_bias := match l.t_bias_grad with | Option.some g => Option.some g.data | Option.none => Option.none
  }) layers

def restoreModelGradSnapshots (layers : List LayerCore) (snaps : List GradSnapshot) : List LayerCore := layers
def freeModelGradSnapshots (snaps : List GradSnapshot) : Unit := ()

def splitInto (core : RSFCore) (x : Tensor) : Except RSFError (Tensor × Tensor) :=
  match x.dims with
  | b :: d2 :: [] =>
    if d2 == core.dim * 2 then
      let x1_data := List.flatten (List.map (fun i => List.take core.dim (List.drop (i * d2) x.data)) (List.range b));
      let x2_data := List.flatten (List.map (fun i => List.take core.dim (List.drop (i * d2 + core.dim) x.data)) (List.range b));
      Except.ok ({ dims := [b, core.dim], data := x1_data }, { dims := [b, core.dim], data := x2_data })
    else Except.error RSFError.ShapeMismatch
  | _ => Except.error RSFError.ShapeMismatch

def mergeFrom (core : RSFCore) (x1 x2 : Tensor) : Except RSFError Tensor :=
  match x1.dims, x2.dims with
  | b1 :: d1 :: [], b2 :: d2 :: [] =>
    if b1 == b2 && d1 == core.dim && d2 == core.dim then
      let out_data := List.flatten (List.map (fun i =>
        let r1 := List.take core.dim (List.drop (i * core.dim) x1.data);
        let r2 := List.take core.dim (List.drop (i * core.dim) x2.data);
        r1 ++ r2
      ) (List.range b1));
      Except.ok { dims := [b1, core.dim * 2], data := out_data }
    else Except.error RSFError.DataLengthMismatch
  | _, _ => Except.error RSFError.DataLengthMismatch

def forwardOnCore (core : RSFCore) (x : Tensor) : Except RSFError Tensor :=
  match validateTensor2D x with
  | Except.ok () =>
    match splitInto core x with
    | Except.ok (x1, x2) =>
      let res := List.foldl (fun acc layer =>
        match acc with
        | Except.ok (curr_x1, curr_x2) => layer.forwardInPlace curr_x1 curr_x2
        | Except.error e => Except.error e
      ) (Except.ok (x1, x2)) core.layers;
      match res with
      | Except.ok (final_x1, final_x2) => mergeFrom core final_x1 final_x2
      | Except.error e => Except.error e
    | Except.error e => Except.error e
  | Except.error e => Except.error e

def inverseOnCore (core : RSFCore) (y : Tensor) : Except RSFError Tensor :=
  match validateTensor2D y with
  | Except.ok () =>
    match splitInto core y with
    | Except.ok (y1, y2) =>
      let res := List.foldr (fun layer acc =>
        match acc with
        | Except.ok (curr_y1, curr_y2) => layer.inverseInPlace curr_y1 curr_y2
        | Except.error e => Except.error e
      ) (Except.ok (y1, y2)) core.layers;
      match res with
      | Except.ok (final_y1, final_y2) => mergeFrom core final_y1 final_y2
      | Except.error e => Except.error e
    | Except.error e => Except.error e
  | Except.error e => Except.error e

def backwardOnCore (core : RSFCore) (grad_output input grad_input_out : Tensor) : Except RSFError (RSFCore × Tensor) :=
  Except.ok (core, grad_input_out)

def layerGPUCompatible (layer : LayerCore) : Bool :=
  if layer.clip_min == -5.0 && layer.clip_max == 5.0 then true else false

def modelGPUCompatible (core : RSFCore) : Bool :=
  if core.num_layers == 1 && core.layers.length == 1 then
    match List.get? core.layers 0 with
    | Option.some l => layerGPUCompatible l
    | Option.none => false
  else false

def disableGPU (core : RSFCore) : RSFCore :=
  { core with gpu_available := false, gpu_weight_version := 0 }

def ensureGPUInitialized (core : RSFCore) : Except RSFError RSFCore :=
  if modelGPUCompatible core then Except.ok core else Except.error RSFError.GPUUnsupportedConfiguration

def validateF16Convertible (data : List Float) : Except RSFError Unit := Except.ok ()

def syncAllLayersGPU (core : RSFCore) : Except RSFError RSFCore :=
  match ensureGPUInitialized core with
  | Except.ok c => Except.ok { c with gpu_available := true, gpu_weight_version := c.cpu_weight_version }
  | Except.error e => Except.error e

def invalidateGPUForMismatch (core : RSFCore) : RSFCore :=
  { core with gpu_available := false }

structure RSF where
  id : Nat
  ctrl : RSFCore

def RSF.init (dim num_layers : Nat) : Except RSFError RSF :=
  if dim == 0 then Except.error RSFError.InvalidDimension else
  if num_layers == 0 then Except.error RSFError.InvalidLayerCount else
  Except.ok { id := 1, ctrl := { dim := dim, num_layers := num_layers, layers := [], cfg := { clip_min := -5.0, clip_max := 5.0, grad_mean := true, max_dim := 1048576, max_layers := 1048576 }, gpu_available := false, gpu_weight_version := 0, cpu_weight_version := 1 } }

def RSF.initWithConfig (dim num_layers : Nat) (cfg : RSFConfig) : Except RSFError RSF :=
  if dim == 0 then Except.error RSFError.InvalidDimension else
  if num_layers == 0 then Except.error RSFError.InvalidLayerCount else
  if dim > cfg.max_dim || num_layers > cfg.max_layers then Except.error RSFError.TooLarge else
  if cfg.clip_min ≥ cfg.clip_max then Except.error RSFError.InvalidConfig else
  if cfg.clip_max > 20.0 || cfg.clip_min < -20.0 then Except.error RSFError.InvalidConfig else
  Except.ok { id := 1, ctrl := { dim := dim, num_layers := num_layers, layers := [], cfg := cfg, gpu_available := false, gpu_weight_version := 0, cpu_weight_version := 1 } }

def RSF.deinit (rsf : RSF) : Unit := ()

def RSF.isGPUAvailable (rsf : RSF) : Bool := rsf.ctrl.gpu_available

def RSF.syncWeightsToGPU (rsf : RSF) : Except RSFError RSF :=
  match syncAllLayersGPU rsf.ctrl with
  | Except.ok c => Except.ok { rsf with ctrl := c }
  | Except.error e => Except.error e

def RSF.zeroGradients (rsf : RSF) : RSF :=
  { rsf with ctrl := { rsf.ctrl with layers := List.map LayerCore.zeroGradients rsf.ctrl.layers } }

def RSF.forwardCPU (rsf : RSF) (x : Tensor) : Except RSFError Tensor :=
  forwardOnCore rsf.ctrl x

def RSF.forward (rsf : RSF) (x : Tensor) : Except RSFError Tensor :=
  forwardOnCore rsf.ctrl x

def RSF.inverse (rsf : RSF) (y : Tensor) : Except RSFError Tensor :=
  inverseOnCore rsf.ctrl y

def RSF.backward (rsf : RSF) (grad_output input grad_input_out : Tensor) : Except RSFError (RSF × Tensor) :=
  match backwardOnCore rsf.ctrl grad_output input grad_input_out with
  | Except.ok (c, t) => Except.ok ({ rsf with ctrl := c }, t)
  | Except.error e => Except.error e

def RSF.save (rsf : RSF) : List UInt8 := []

def RSF.load (bytes : List UInt8) : Except RSFError RSF := Except.error RSFError.BadFileFormat

